CREATE TABLE IF NOT EXISTS m2_course(id VARCHAR(32) PRIMARY KEY,title VARCHAR(200) NOT NULL,description VARCHAR(2000) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS m2_prerequisite(course_id VARCHAR(32) NOT NULL,prerequisite_id VARCHAR(32) NOT NULL,PRIMARY KEY(course_id,prerequisite_id),FOREIGN KEY(course_id) REFERENCES m2_course(id),FOREIGN KEY(prerequisite_id) REFERENCES m2_course(id),CHECK(course_id<>prerequisite_id));
CREATE TABLE IF NOT EXISTS m2_completed(student_id VARCHAR(64) NOT NULL,course_id VARCHAR(32) NOT NULL,PRIMARY KEY(student_id,course_id),FOREIGN KEY(course_id) REFERENCES m2_course(id));
CREATE TABLE IF NOT EXISTS m2_profile(student_id VARCHAR(64) PRIMARY KEY,interests VARCHAR(500) NOT NULL,goals VARCHAR(300) NOT NULL);
CREATE TABLE IF NOT EXISTS m2_history(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,student_id VARCHAR(64) NOT NULL,query_text VARCHAR(801) NOT NULL,results_json TEXT NOT NULL,created_at TIMESTAMP NOT NULL);
CREATE INDEX IF NOT EXISTS ix_m2_history_student ON m2_history(student_id,id);
